<?php
require 'includes/bootstrap.php';
$lista=$pdo->query("SELECT o.*,c.nome cliente,(SELECT COALESCE(SUM(i.quantidade*i.valor_unitario),0) FROM orcamentos_itens i WHERE i.orcamento_id=o.id)-o.desconto total FROM orcamentos_orcamentos o JOIN orcamentos_clientes c ON c.id=o.cliente_id ORDER BY o.id DESC")->fetchAll();require 'includes/header.php';?>
<div class="page-head"><h1>Orçamentos</h1><a class="btn" href="orcamento_editar.php">Novo orçamento</a></div><table><thead><tr><th>Nº</th><th>Cliente</th><th>Título</th><th>Data</th><th>Total</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($lista as $r):?><tr><td>#<?= (int)$r['numero'] ?></td><td><?= e($r['cliente']) ?></td><td><?= e($r['titulo']) ?></td><td><?= date('d/m/Y',strtotime($r['data_emissao'])) ?></td><td><?= money((float)$r['total']) ?></td><td><?= e($r['status']) ?></td><td class="actions"><a class="btn secondary" href="orcamento_ver.php?id=<?= (int)$r['id'] ?>">Ver</a><a class="btn secondary" href="orcamento_editar.php?id=<?= (int)$r['id'] ?>">Editar</a><a class="btn" target="_blank" href="orcamento_pdf.php?id=<?= (int)$r['id'] ?>">PDF</a></td></tr><?php endforeach;?></tbody></table><?php require 'includes/footer.php';?>
